*{box-sizing:border-box}html,body{height:100%;margin:0}body{background:#151d1b;color:var(--ink);font-family:var(--mono);overflow:hidden}.game-shell{position:relative;width:100%;height:100dvh;min-height:500px;overflow:hidden;background:#1a2926;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.film-grain{position:absolute;inset:-50%;z-index:2;pointer-events:none;opacity:.12;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.88' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.48'/%3E%3C/svg%3E");animation:grain .22s steps(2) infinite}.vignette{position:absolute;inset:0;z-index:2;pointer-events:none;background:radial-gradient(ellipse at 51% 47%,transparent 35%,rgba(9,15,14,.2) 75%,rgba(8,12,11,.75) 140%),linear-gradient(180deg,rgba(10,15,14,.28),transparent 25%,transparent 77%,rgba(10,14,14,.3)}.film-frame{position:absolute;inset:14px;z-index:3;pointer-events:none;border:1px solid rgba(241,221,175,.22)}.film-frame:before,.film-frame:after{content:'';position:absolute;left:8px;right:8px;border-top:1px solid rgba(241,221,175,.10)}.film-frame:before{top:7px}.film-frame:after{bottom:7px}.film-frame i{position:absolute;top:50%;width:4px;height:4px;background:rgba(241,221,175,.5);border-radius:50%}.film-frame i:nth-child(1){left:-2px;top:-2px}.film-frame i:nth-child(2){right:-2px;top:-2px}.film-frame i:nth-child(3){left:-2px;top:auto;bottom:-2px}.film-frame i:nth-child(4){right:-2px;top:auto;bottom:-2px}.topbar{position:absolute;z-index:5;top:0;left:0;right:0;height:76px;padding:0 6.2%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(241,221,175,.14)}.wordmark{text-decoration:none;color:var(--ink);display:flex;align-items:center;gap:10px;font:18px var(--display);letter-spacing:1px}.wordmark small{displ