    soundIcon: $('soundIcon'), distance: $('distance'), coins: $('coins'), best: $('best'),
    finalDistance: $('finalDistance'), finalCoins: $('finalCoins'), scoreboard: $('scoreboard'),
    controls: $('controlsHint'), toast: $('toast'), audioCaption: $('audioCaption')
  };
  const colors = { ink:'#f1dfb8', gold:'#e1bc71', pale:'#fff0cd', dark:'#263834', shadow:'#14201e', red:'#a85140', muted:'#99846b' };
