    ctx.fillStyle='rgba(119,103,84,.18)';ctx.beginPath();ctx.arc(moonX-moonR*.17,moonY-moonR*.18,moonR*.84,0,Math.PI*2);ctx.fill();
    // Thin drifting cloud bands.
