  function drawCity(hg,t){
    const baseline=hg+H*.045,unit=W/18;
    for(let layer=0;layer<2;layer++){
      const step=layer?42:55, offset=((t*(game.mode==='playing'?8:1)+layer*70)%step);
      for(let x=-step;x<W+step;x+=step){
        const seed=Math.floor((x+offset+layer*31)/step)+layer*300;
        const bw=step*(.62+rng(seed)*.55), bh=H*(.07+rng(seed+8)*(.12+layer*.05));
        const bx=x-offset, by=baseline-bh;
        ctx.fillStyle=layer?'#35413c':'#2a3734';ctx.fillRect(bx,by,bw,bh);
