    ctx.fillStyle='rgba(240,212,150,.22)';ctx.beginPath();ctx.arc(cx,sy+sh*.25,H*.027,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#594a3a';ctx.font=`${Math.max(6,W*.008)}px SpecialElite,monospace`;ctx.textAlign='center';ctx.fillText('MARIGOLD CENTRAL',cx,sy+sh*.19);
