function drawCoin(x,y,s,glint=0){
  const r=13*s;ctx.save();ctx.translate(x,y);ctx.rotate(Math.sin(game.time*4+glint)*.08);
  ctx.shadowColor='rgba(255,199,92,.85)';ctx.shadowBlur=15*s;
