    ctx.fillStyle='#a84f3e';ctx.beginPath();ctx.moveTo(-12*s,-10*s);ctx.lineTo(-15*s,15*s);ctx.lineTo(0,11*s);ctx.lineTo(14*s,16*s);ctx.lineTo(12*s,-10*s);ctx.closePath();ctx.fill();
    ctx.fillStyle='#e0bd79';ctx.beginPath();ctx.moveTo(-4*s,-8*s);ctx.lineTo(0,4*s);ctx.lineTo(4*s,-8*s);ctx.lineTo(1*s,14*s);ctx.closePath();ctx.fill();
    // arms swing on opposing beats
    ctx.strokeStyle='#a84f3e';ctx.lineWidth=6*s;
    ctx.beginPath();ctx.moveTo(-10*s,-4*s);ctx.lineTo((-18-run*7)*s,(5+run*4)*s);ctx.moveTo(10*s,-4*s);ctx.lineTo((17+run*7)*s,(5-run*4)*s);ctx.stroke();
    // head, scarf, and jaunty fedora
    ctx.fillStyle='#e7c28b';ctx.beginPath();ctx.arc(0,-18*s,10*s,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#293a35';ctx.fillRect(-12*s,-28*s,24*s,5*s);ctx.fillRect(-7*s,-38*s,15*s,11*s);
    ctx.fillStyle='#af5540';ctx.fillRect(-7*s,-29*s,15*s,3*s);
    ctx.fillStyle='#312923';ctx.beginPath();ctx.arc(3*s,-19*s,1.4*s,0,Math.PI*2);ctx.fill();
