function render(now){
  const t=now/1000;game.time=t;
  ctx.clearRect(0,0,W,H);
  drawSky(t);drawTracks(t);
  if(game.items.length){for(const item of [...game.items].sort((a,b)=>b.z-a.z))drawItem(item)}
  drawRunner();
  // wandering cinders, deliberately sparse like dust on a projection gate
  for(let i=0;i<12;i++){
    const x=rng(i+Math.floor(t*2))*W,y=((rng(i+200)+t*(.03+rng(i)*.04))%1)*H;
