  function addItem(type,lane,z=1.03,phase=Math.random()*6){game.items.push({type,lane,z,phase,hit:false})}
  function spawnPattern(){
    const n=Math.floor(game.distance/9+game.elapsed*1.1), lane=Math.floor(Math.random()*3), other=(lane+1+Math.floor(Math.random()*2))%3;
    const kind=n%7;
    if(kind===0||kind===4){
      addItem('crate',lane);
      for(let i=0;i<5;i++)addItem('coin',other,1.04+i*.082,i*.8);
    } else if(kind===1){
      addItem('gate',lane);
      for(let i=0;i<5;i++)addItem('coin',(lane+1)%3,1.03+i*.08,i);
    } else if(kind===2){
      addItem('train',lane);
      for(let i=0;i<4;i++)addItem('coin',other,1.05+i*.1,i);
    } else if(kind===3){
      for(let i=0;i<6;i++)addItem('coin',lane,1.02+i*.085,i*.4);
      addItem('crate',other,1.31);
    } else if(kind===5){
      addItem('crate',lane);addItem('gate',other,1.30);
      for(let i=0;i<4;i++)addItem('coin',(lane+2)%3,1.02+i*.09,i);
    } else {
      for(let i=0;i<5;i++)addItem('coin',lane,1.02+i*.09,i);
      addItem('train',other,1.28);
    }
  }
  function tick(now){
    if(!game.last)game.last=now;
    const dt=Math.min(.04,(now-game.last)/1000);game.last=now;
    if(game.mode==='playing'){
      game.elapsed+=dt;game.distance+=game.speed*dt*15;
      game.speed=Math.min(.73,.34+game.distance*.00052);
      game.laneVisual=lerp(game.laneVisual,game.lane,1-Math.exp(-dt*13));
      game.jump=Math.max(0,game.jump-dt);game.slide=Math.max(0,game.slide-dt);
      game.spawn-=dt;
      if(game.spawn<=0){spawnPattern();game.spawn=clamp(1.05-game.speed*.46,.68,.94)}
      for(const item of game.items){
        item.z-=game.speed*dt;
        if(!item.hit&&item.z<.105&&item.z>.04){
          item.hit=true;
          if(item.lane===game.lane){
            if(item.type==='coin'){
              game.coins++;updateScore();playTone(784,.09,.045,'sine');
            }else if(item.type==='crate'&&game.jump>.23){/* clean jump */}
            else if(item.type==='gate'&&game.slide>.18){/* perfect duck */}
            else {game.hitFlash=1;endGame();break}
          }
        }
      }
      game.items=game.items.filter(i=>i.z>-.08);
      updateScore();
      if(game.elapsed>20&&ui.controls.classList.contains('hidden')===false){ui.controls.classList.add('hidden')}
    }
    requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
  function updateScore(){
    ui.distance.textContent=String(Math.floor(game.distance)).padStart(3,'0');
    ui.coins.textContent=String(game.coins).padStart(2,'0');
  }
  function showScreen(which){
    for(const el of [ui.title,ui.pause,ui.over])el.classList.remove('visible');
    if(which)which.classList.add('visible');
  }
  function resetGame(){
    game.mode='playing';game.lane=1;game.laneVisual=1;game.jump=0;game.slide=0;game.distance=0;game.coins=0;game.speed=.34;game.items=[];game.spawn=.6;game.elapsed=0;game.hitFlash=0;
    updateScore();showScreen(null);ui.scoreboard.classList.add('active');ui.controls.classList.remove('hidden');ui.pauseIndicator.classList.add('show');ui.audioCaption.style.opacity='1';
    ensureAudio();musicOn();
  }
  function endGame(){
    if(game.mode!=='playing')return;
    game.mode='over';
    const score=Math.floor(game.distance);
    if(score>game.best){game.best=score;localStorage.setItem('marigold-best',score);ui.best.textContent=String(score).padStart(3,'0')+'m';showToast('A NEW MARIGOLD RECORD ✦')}
    ui.finalDistance.innerHTML=String(score).padStart(3,'0')+'<span>m</span>';
    ui.finalCoins.textContent=game.coins;
    showScreen(ui.over);ui.pauseIndicator.classList.remove('show');ui.controls.classList.add('hidden');musicOn();playTone(196,.5,.08,'triangle');
  }
  function pauseGame(){if(game.mode==='playing'){game.mode='paused';showScreen(ui.pause);ui.controls.classList.add('hidden');musicOn()}}
  function resumeGame(){if(game.mode==='paused'){game.mode='playing';showScreen(null);ui.controls.classList.remove('hidden');musicOn()}}
  function move(action){
    if(game.mode==='title'){if(action==='jump'||action==='left'||action==='right')resetGame();return}
    if(game.mode==='over'){if(action==='jump')resetGame();return}
    if(game.mode==='paused')return;
    if(action==='left')game.lane=Math.max(0,game.lane-1);
    if(action==='right')game.lane=Math.min(2,game.lane+1);
    if(action==='jump'&&game.jump<=0&&game.slide<=0){game.jump=.8;playTone(440,.08,.04,'triangle')}
    if(action==='slide'&&game.slide<=0&&game.jump<=0){game.slide=.58;playTone(260,.07,.025,'sine')}
  }
  function showToast(message){ui.toast.textContent=message;ui.toast.classList.add('show');clearTimeout(game.toastTimer);game.toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}
  ui.start.addEventListener('click',resetGame);ui.restart.addEventListener('click',resetGame);ui.resume.addEventListener('click',resumeGame);
  ui.pauseBtn.addEventListener('click',()=>game.mode==='playing'?pauseGame():resumeGame());
  ui.pauseIndicator.addEventListener('click',pauseGame);
  document.addEventListener('keydown',e=>{
    const key=e.key.toLowerCase();
    if(['arrowleft','arrowright','arrowup','arrowdown',' ','w','a','s','d'].includes(key))e.preventDefault();
    if(key==='escape'||key==='p'){if(game.mode==='playing')pauseGame();else if(game.mode==='paused')resumeGame();return}
    if(key==='arrowleft'||key==='a')move('left');
    else if(key==='arrowright'||key==='d')move('right');
    else if(key==='arrowup'||key==='w'||key===' ')move('jump');
    else if(key==='arrowdown'||key==='s')move('slide');
  });
  document.querySelectorAll('.touch-controls button').forEach(button=>button.addEventListener('pointerdown',e=>{e.preventDefault();move(button.dataset.move)}));
  let touchStart=null;
  canvas.addEventListener('touchstart',e=>{const p=e.changedTouches[0];touchStart=[p.clientX,p.clientY]}, {passive:true});
  canvas.addEventListener('touchend',e=>{
    if(!touchStart)return;const p=e.changedTouches[0],dx=p.clientX-touchStart[0],dy=p.clientY-touchStart[1];touchStart=null;
    if(Math.max(Math.abs(dx),Math.abs(dy))<24)return;
    if(Math.abs(dx)>Math.abs(dy))move(dx<0?'left':'right');else move(dy<0?'jump':'slide');
  },{passive:true});
  ui.soundBtn.addEventListener('click',()=>{
    game.audioOn=!game.audioOn;ui.soundBtn.classList.toggle('off',!game.audioOn);ui.soundIcon.textContent=game.audioOn?'♫':'♪';ui.soundBtn.setAttribute('aria-label',game.audioOn?'Turn sound off':'Turn sound on');
    if(game.audioOn){ensureAudio();musicOn()}else musicOff();
  });
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&game.mode==='playing')pauseGame()});

  function ensureAudio(){
    if(!game.audioOn)return;
    if(!ac){const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;ac=new Audio();master=ac.createGain();master.gain.value=.18;master.connect(ac.destination)}
    if(ac.state==='suspended')ac.resume();
  }
  function playTone(freq,duration=.18,volume=.05,wave='sine',delay=0){
    if(!game.audioOn)return;ensureAudio();if(!ac)return;
    const osc=ac.createOscillator(),gain=ac.createGain(),now=ac.currentTime+delay;
    osc.type=wave;osc.frequency.setValueAtTime(freq,now);gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(volume,now+.012);gain.gain.exponentialRampToValueAtTime(.0001,now+duration);
    osc.connect(gain);gain.connect(master);osc.start(now);osc.stop(now+duration+.03);
  }
  function musicOn(){
    if(!game.audioOn||musicTimer)return;ensureAudio();if(!ac)return;
    const melody=[392,0,440,523.25,0,587.33,523.25,0,440,0,392,329.63,0,349.23,392,0,293.66,0,349.23,440,0,392,349.23,0];
    const bass=[130.81,0,164.81,0,146.83,0,110,0];
    musicTimer=setInterval(()=>{
      if(!game.audioOn||!ac||game.mode==='paused')return;
      const n=beat++%melody.length;
      if(melody[n])playTone(melody[n],.27,.022,'triangle');
      if(n%3===0)playTone(melody[(n+4)%melody.length]*2,.22,.009,'sine',.04);
      const b=bass[beat%bass.length];if(b)playTone(b,.37,.045,'sine');
      // soft click-clack on alternating beats: the railway is keeping time.
      if(n%2===0)playTone(n%4===0?94:72,.035,.012,'square');
    },285);
  }
  function musicOff(){if(musicTimer){clearInterval(musicTimer);musicTimer=null}}
  musicOn();
})();

