content.text:
.topbar{position:absolute;z-index:5;top:0;left:0;right:0;height:76px;padding:0 6.2%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(241,221,175,.14)}
.scoreboard{position:absolute;z-index:4;top:99px;left:6.5%;display:flex;align-items:center;gap:25px;opacity:0;transform:translateY(-7px);transition:opacity .35s,transform .35s;pointer-events:none}
.scoreboard.active{opacity:1;transform:translateY(0)}
.chapter-tag{position:absolute;z-index:4;top:106px;right:6.8%;font-size:9px;letter-spacing:2px;color:rgba(241,221,175,.78)}
.audio-caption{position:absolute;z-index:4;right:6.8%;bottom:83px;display:flex;gap:8px;align-items:center;font-size:8px;letter-spacing:1.5px;color:rgba(241,221,175,.62);transition:opacity .3s}
.audio-caption #trackName{color:var(--gold)}
.title-screen,.screen{position:absolute;z-index:5;left:50%;top:47%;transform:translate(-50%,-50%);text-align:center;width:min(760px,88vw);transition:opacity .35s,visibility .35s;pointer-events:none}
.screen{visibility:hidden;opacity:0}
.screen.visible{visibility:visible;opacity:1;pointer-events:auto}
.title-screen h1{font:clamp(54px,8.4vw,112px)/.79 var(--display);letter-spacing:1px;color:#f5e4bd;margin:21px 0 0;text-shadow:0 4px 1px rgba(0,0,0,.2),0 0 35px rgba(237,185,101,.15)}
.screen-eyebrow{font-size:9px;letter-spacing:2.4px;color:#d7b76f;margin:6px 0 11px}
.pause-indicator{position:absolute;z-index:5;right:6.8%;top:110px;border:1px solid rgba(241,221,175,.4);padding:8px 11px;color:var(--ink);font-size:9px;letter-spacing:1.5px;cursor:pointer;display:none;background:rgba(24,36,33,.5)}
.pause-indicator.show{display:flex;gap:8px;align-items:center}
.pause-indicator span:first-child{color:var(--gold);font-size:12px}
.controls-hint{position:absolute;z-index:4;bottom:85px;left:50%;transform:translateX(-50%);display:flex;gap:7px;align-items:center;font-size:8px;letter-spacing:1.3px;color:rgba(241,221,175,.71);white-space:nowrap;transition:opacity .25s}
.controls-hint.hidden{opacity:0}
.bottom-bar{position:absolute;z-index:5;bottom:0;left:0;right:0;height:47px;border-top:1px solid rgba(241,221,175,.17);padding:0 6.2%;display:flex;align-items:center;justify-content:space-between;color:rgba(241,221,175,.62);font-size:8px;letter-spacing:1.4px}
.bottom-bar b{font:8px var(--serif);padding-left:2px}
.bottom-bar button{display:flex;align-items:center;gap:7px;border:0;background:none;color:rgba(241,221,175,.8);font:9px var(--mono);letter-spacing:1px;cursor:pointer}
.bottom-bar button:hover{color:#f3d183}
.bottom-bar button>span:first-child{color:var(--gold);font-size:12px}

